## 5. Setup do Pinia (Gerenciamento de Estado)

```typescript
// store/index.ts
import { defineStore } from 'pinia'

export const useUserStore = defineStore('user', {
  state: () => ({
    user: null as User | null,
    isAuthenticated: false,
    isLoading: false,
  }),

  getters: {
    isLoggedIn: (state) => state.isAuthenticated,
    currentUser: (state) => state.user,
  },

  actions: {
    setUser(user: User) {
      this.user = user
      this.isAuthenticated = !!user
    },
    logout() {
      this.user = null
      this.isAuthenticated = false
    },
  },
})

// types/user.ts
export interface User {
  id: string
  email: string
  name: string
  avatar?: string
}
```

## 6. Componentes UI Reutilizáveis

```vue
<!-- components/ui/Button.vue -->
<template>
  <button
    :class="buttonClasses"
    @click="handleClick"
    :disabled="isDisabled"
  >
    <slot />
  </button>
</template>

<script setup lang="ts">
import { defineProps, defineEmits } from 'vue'

interface ButtonProps {
  variant?: 'primary' | 'secondary' | 'danger'
  size?: 'sm' | 'md' | 'lg'
  disabled?: boolean
  class?: string
}

const props = defineProps<{
  variant?: ButtonProps['variant']
  size?: ButtonProps['size']
  disabled?: boolean
  class?: string
}>()

const emit = defineEmits<{
  (e: 'click', value?: string): void
}>()

const buttonClasses = computed(() => {
  const base = 'rounded-lg font-medium transition-colors'

  switch (props.variant) {
    case 'primary':
      base += ' bg-blue-600 text-white hover:bg-blue-700'
      break
    case 'secondary':
      base += ' bg-gray-200 text-gray-800 hover:bg-gray-300'
      break
    case 'danger':
      base += ' bg-red-600 text-white hover:bg-red-700'
      break
  }

  if (props.size === 'sm') base += ' py-1.5 px-3'
  else if (props.size === 'lg') base += ' py-4 px-6'

  return `${base} ${props.class || ''}`
})

const handleClick = () => {
  if (!props.disabled) {
    emit('click')
  }
}
</script>
```

